INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Wird für die Verkabelung von Netzwerken häufig Twisted-Pair-Kabel verwendet?', 2, '[{"text": "Ja", "correct": true, "because": "Twisted-Pair (z. B. Cat5e, Cat6) ist Standard"}, {"text": "Nein", "correct": false, "because": "Twisted-Pair ist weit verbreitet"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Verkabelung nach TIA/EIA-568-B T568B ein gültiger Standard?', 2, '[{"text": "Ja", "correct": true, "because": "T568B ist ein anerkannter Verkabelungsstandard"}, {"text": "Nein", "correct": false, "because": "T568B ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Glasfaserkabel für Netzwerkverkabelung verwendet werden?', 2, '[{"text": "Ja", "correct": true, "because": "Glasfaser wird für hohe Bandbreiten genutzt"}, {"text": "Nein", "correct": false, "because": "Glasfaser ist eine Option"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Verkabelung eines Netzwerks immer sichtbar verlegt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Verkabelung kann versteckt (z. B. in Wänden) erfolgen"}, {"text": "Ja", "correct": false, "because": "Versteckte Verlegung ist üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Koaxialkabel noch üblich für moderne Ethernet-Netzwerke?', 2, '[{"text": "Nein", "correct": true, "because": "Koaxialkabel wurden durch Twisted-Pair ersetzt"}, {"text": "Ja", "correct": false, "because": "Koaxial ist veraltet"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Kabeltyp wird am häufigsten für strukturierte Verkabelung verwendet?', 2, '[{"text": "Cat6", "correct": true, "because": "Cat6 bietet hohe Bandbreite und ist weit verbreitet"}, {"text": "Koaxialkabel", "correct": false, "because": "Veraltet für Ethernet"}, {"text": "USB-Kabel", "correct": false, "because": "Nicht für Netzwerke"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Standard definiert die Farbcodierung für Twisted-Pair-Verkabelung?', 3, '[{"text": "TIA/EIA-568-B", "correct": true, "because": "Definiert T568A und T568B"}, {"text": "IEEE 802.3", "correct": false, "because": "Regelt Ethernet, nicht Verkabelung"}, {"text": "ISO 9001", "correct": false, "because": "Qualitätsmanagement, nicht Verkabelung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche maximale Länge darf ein Cat5e-Kabel für Gigabit-Ethernet haben?', 2, '[{"text": "100 Meter", "correct": true, "because": "100 m ist der Standard für Ethernet"}, {"text": "50 Meter", "correct": false, "because": "Zu kurz"}, {"text": "200 Meter", "correct": false, "because": "Zu lang"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Stecker wird für Twisted-Pair-Netzwerkkabel verwendet?', 2, '[{"text": "RJ45", "correct": true, "because": "RJ45 ist der Standardstecker"}, {"text": "RJ11", "correct": false, "because": "Für Telefonie"}, {"text": "BNC", "correct": false, "because": "Für Koaxialkabel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kategorie unterstützt Geschwindigkeiten bis 10 Gbit/s über 100 Meter?', 2, '[{"text": "Cat6a", "correct": true, "because": "Cat6a ist für 10 Gbit/s ausgelegt"}, {"text": "Cat5e", "correct": false, "because": "Nur bis 1 Gbit/s"}, {"text": "Cat7", "correct": false, "because": "Bis 100 m auch, aber überdimensioniert"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Kabeltypen werden für Netzwerkverkabelung verwendet?', 4, '[{"text": "Twisted-Pair (Cat5e)", "correct": true, "because": "Standard für Ethernet"}, {"text": "Glasfaser", "correct": true, "because": "Für hohe Bandbreiten"}, {"text": "Koaxialkabel", "correct": true, "because": "Veraltet, aber möglich"}, {"text": "HDMI", "correct": false, "because": "Nicht für Netzwerke"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Standards gelten für Twisted-Pair-Verkabelung?', 3, '[{"text": "T568A", "correct": true, "because": "Ein TIA/EIA-568-Standard"}, {"text": "T568B", "correct": true, "because": "Ein weiterer TIA/EIA-568-Standard"}, {"text": "IEEE 802.11", "correct": false, "because": "Für WLAN, nicht Verkabelung"}, {"text": "TIA/EIA-568-B", "correct": true, "because": "Definiert Verkabelung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren sind bei der Netzwerkverkabelung wichtig?', 4, '[{"text": "Kabellänge", "correct": true, "because": "Max. 100 m für Ethernet"}, {"text": "Kabelkategorie", "correct": true, "because": "Bestimmt Bandbreite"}, {"text": "Farbe des Kabels", "correct": false, "because": "Nur organisatorisch relevant"}, {"text": "Abschirmung", "correct": true, "because": "Schützt vor Störungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Glasfaserverkabelung?', 3, '[{"text": "Hohe Bandbreite", "correct": true, "because": "Bis zu 100 Gbit/s und mehr"}, {"text": "Große Reichweite", "correct": true, "because": "Kilometer statt 100 m"}, {"text": "Geringe Kosten", "correct": false, "because": "Glasfaser ist teurer"}, {"text": "Störunanfälligkeit", "correct": true, "because": "Keine elektromagnetischen Störungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Werkzeuge werden für die Verkabelung benötigt?', 3, '[{"text": "Crimper", "correct": true, "because": "Für RJ45-Stecker"}, {"text": "Kabeltester", "correct": true, "because": "Prüft Verbindungen"}, {"text": "Abisolierzange", "correct": true, "because": "Entfernt Isolierung"}, {"text": "Schraubendreher", "correct": false, "because": "Nicht spezifisch nötig"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Cat6 unterstützt 10 Gbit/s über 55 Meter. b) Koaxialkabel sind der aktuelle Standard.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Cat6 ja, Koaxial veraltet"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) T568B ist ein Verkabelungsstandard. b) Glasfaser ist langsamer als Twisted-Pair.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "T568B ja, Glasfaser schneller"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Cat5e unterstützt Gigabit-Ethernet. b) RJ45 wird für Glasfaserkabel verwendet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Cat5e ja, RJ45 ist für Twisted-Pair"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Verkabelung darf 100 Meter nicht überschreiten. b) Abschirmung schützt vor Störungen.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "100 m ist Ethernet-Limit, Abschirmung hilft"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Glasfaserkabel sind teurer als Twisted-Pair. b) Cat7 ist für 1 Gbit/s ausgelegt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Glasfaser teurer, Cat7 bis 10 Gbit/s"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

